(function() {
    'use strict';

    class DestinationMakerAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'DestinationMaker: Tourism Destination Management';
            this.version = '1.1.0';

            this.SEGMENTS = {
                families:       { digital: 0.90, ota: 1.20, pr: 0.80, spend: 350, volumeFactor: 1.20 },
                couples:        { digital: 1.00, ota: 1.00, pr: 1.10, spend: 420, volumeFactor: 1.00 },
                adventure:      { digital: 1.30, ota: 0.80, pr: 1.20, spend: 380, volumeFactor: 0.90 },
                luxury:         { digital: 0.70, ota: 0.60, pr: 1.30, spend: 650, volumeFactor: 0.50 },
                digital_natives:{ digital: 1.40, ota: 1.10, pr: 1.00, spend: 280, volumeFactor: 1.40 }
            };

            this.BRANDS = {
                heritage:       { families: 0.85, couples: 1.10, adventure: 0.95, luxury: 1.20, digital_natives: 0.75, premium: 1.12 },
                luxury_escape:  { families: 0.60, couples: 1.25, adventure: 0.70, luxury: 1.40, digital_natives: 0.50, premium: 1.25 },
                affordable:     { families: 1.35, couples: 0.80, adventure: 0.65, luxury: 0.35, digital_natives: 1.20, premium: 0.85 },
                adventure_brand:{ families: 0.70, couples: 0.90, adventure: 1.40, luxury: 0.80, digital_natives: 1.10, premium: 1.08 },
                wellness:       { families: 0.55, couples: 1.20, adventure: 0.60, luxury: 1.30, digital_natives: 0.60, premium: 1.20 }
            };

            this.ROUND_BRIEFINGS = [
                {
                    icon: '📊',
                    titleKey: 'brief1_title',
                    textKey: 'brief1_text'
                },
                {
                    icon: '🏗️',
                    titleKey: 'brief2_title',
                    textKey: 'brief2_text'
                },
                {
                    icon: '🌿',
                    titleKey: 'brief3_title',
                    textKey: 'brief3_text'
                }
            ];

            this.EVENTS = [
                {
                    titleKey: 'event1_title',
                    textKey: 'event1_text'
                },
                {
                    titleKey: 'event2_title',
                    textKey: 'event2_text'
                },
                {
                    titleKey: 'event3_title',
                    textKey: 'event3_text'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 15,
                    visitors: 1.2,
                    avgSpend: 387,
                    annualRevenue: 465,
                    cumulativeRevenue: 0,
                    nps: 45,
                    sustainabilityIndex: 30,
                    communityScore: 50,
                    brandPosition: '',
                    targetSegment: '',
                    commercialization: 5,
                    revenueHistory: [],
                    npsHistory: [],
                    sustainHistory: [],
                    communityHistory: [],
                    overallScoreHistory: [],
                    eventLog: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    brand: 'heritage',
                    segment: 'couples',
                    digital: 30,
                    ota: 35,
                    pr: 25,
                    cultural: 40,
                    beach: 35,
                    gastro: 25,
                    commercialization: 5,
                    visitorCap: 5500,
                    communityShare: 8,
                    certInvest: 10,
                    expansion: 5
                };
            }
            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function' && !this._reactBound) {
                // FIX(v1.1.0): the framework's undo restores state but never re-invokes
                // the adapter view, leaving the wrong round's decision panel visible;
                // language changes must re-render the localized briefing. Keep both reactive.
                this._reactBound = true;
                sim.eventBus.on('period:undone', function(st) { self._updateBriefing(st || sim.state); });
                sim.eventBus.on('language:changed', function() { self._updateBriefing(sim.state); });
            }
            this._updateBriefing(state);
            this._setupInputListeners();
        }

        _setupInputListeners() {
            var digiEl = document.getElementById('digitalInput');
            var otaEl = document.getElementById('otaInput');
            var prEl = document.getElementById('prInput');
            var allocEl = document.getElementById('r1AllocDisplay');
            function updateR1() {
                var total = (parseFloat(digiEl.value) || 0) + (parseFloat(otaEl.value) || 0) + (parseFloat(prEl.value) || 0);
                if (allocEl) allocEl.textContent = total + '%';
            }
            if (digiEl) digiEl.addEventListener('input', updateR1);
            if (otaEl) otaEl.addEventListener('input', updateR1);
            if (prEl) prEl.addEventListener('input', updateR1);

            var culEl = document.getElementById('culturalInput');
            var beaEl = document.getElementById('beachInput');
            var gasEl = document.getElementById('gastroInput');
            var alloc2 = document.getElementById('r2AllocDisplay');
            function updateR2() {
                var total = (parseFloat(culEl.value) || 0) + (parseFloat(beaEl.value) || 0) + (parseFloat(gasEl.value) || 0);
                if (alloc2) alloc2.textContent = total + '%';
            }
            if (culEl) culEl.addEventListener('input', updateR2);
            if (beaEl) beaEl.addEventListener('input', updateR2);
            if (gasEl) gasEl.addEventListener('input', updateR2);

            var comEl = document.getElementById('commercialInput');
            var comVal = document.getElementById('commercialValue');
            if (comEl) {
                comEl.addEventListener('input', function() {
                    if (comVal) comVal.textContent = comEl.value;
                });
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUND_BRIEFINGS.length - 1);
            var round = this.ROUND_BRIEFINGS[idx];

            var iconEl = document.getElementById('briefingIcon');
            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');

            if (iconEl) iconEl.textContent = round.icon;
            if (titleEl && window.mySimulation) titleEl.textContent = window.mySimulation.t(round.titleKey);
            if (textEl && window.mySimulation) textEl.innerHTML = window.mySimulation.t(round.textKey);

            var r1 = document.getElementById('round1Panel');
            var r2 = document.getElementById('round2Panel');
            var r3 = document.getElementById('round3Panel');
            if (r1) r1.style.display = (idx === 0) ? 'block' : 'none';
            if (r2) r2.style.display = (idx === 1) ? 'block' : 'none';
            if (r3) r3.style.display = (idx === 2) ? 'block' : 'none';

            var prevEvtIdx = idx - 1;
            var evtPanel = document.getElementById('eventPanel');
            var evtText = document.getElementById('eventText');
            if (prevEvtIdx >= 0 && prevEvtIdx < this.EVENTS.length && state.domainState && state.domainState.eventLog) {
                if (evtPanel) evtPanel.style.display = 'block';
                if (evtText) evtText.innerHTML = state.domainState.eventLog;
            } else {
                if (evtPanel) evtPanel.style.display = 'none';
            }
        }

        validateDecisions(decisions) {
            var period = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state.currentPeriod : 1;

            if (period === 1) {
                var brandEl = document.getElementById('brandSelect');
                var segEl = document.getElementById('segmentSelect');
                var digiEl = document.getElementById('digitalInput');
                var otaEl = document.getElementById('otaInput');
                var prEl = document.getElementById('prInput');
                if (brandEl) decisions.brand = brandEl.value;
                if (segEl) decisions.segment = segEl.value;
                if (digiEl) decisions.digital = parseFloat(digiEl.value) || 0;
                if (otaEl) decisions.ota = parseFloat(otaEl.value) || 0;
                if (prEl) decisions.pr = parseFloat(prEl.value) || 0;

                var totalChannels = decisions.digital + decisions.ota + decisions.pr;
                if (totalChannels > 100) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_channel_over'), 'warning'
                    );
                    return false;
                }
                if (decisions.digital < 0 || decisions.ota < 0 || decisions.pr < 0) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_negative'), 'warning'
                    );
                    return false;
                }
            } else if (period === 2) {
                var culEl = document.getElementById('culturalInput');
                var beaEl = document.getElementById('beachInput');
                var gasEl = document.getElementById('gastroInput');
                var comEl = document.getElementById('commercialInput');
                if (culEl) decisions.cultural = parseFloat(culEl.value) || 0;
                if (beaEl) decisions.beach = parseFloat(beaEl.value) || 0;
                if (gasEl) decisions.gastro = parseFloat(gasEl.value) || 0;
                if (comEl) decisions.commercialization = parseInt(comEl.value) || 5;

                var totalCapex = decisions.cultural + decisions.beach + decisions.gastro;
                if (totalCapex > 100) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_capex_over'), 'warning'
                    );
                    return false;
                }
                if (decisions.cultural < 0 || decisions.beach < 0 || decisions.gastro < 0) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_negative'), 'warning'
                    );
                    return false;
                }
            } else if (period === 3) {
                var capEl = document.getElementById('capInput');
                var shareEl = document.getElementById('shareInput');
                var certEl = document.getElementById('certInput');
                var expEl = document.getElementById('expandInput');
                if (capEl) decisions.visitorCap = parseInt(capEl.value) || 5500;
                if (shareEl) decisions.communityShare = parseFloat(shareEl.value) || 0;
                if (certEl) decisions.certInvest = parseFloat(certEl.value) || 0;
                if (expEl) decisions.expansion = parseFloat(expEl.value) || 0;

                if (decisions.visitorCap < 3000 || decisions.visitorCap > 8000) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_cap_range'), 'warning'
                    );
                    return false;
                }
                if (decisions.communityShare < 0 || decisions.communityShare > 15) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_share_range'), 'warning'
                    );
                    return false;
                }
                if (decisions.certInvest + decisions.expansion > 30) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_sustain_over'), 'warning'
                    );
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var period = state.currentPeriod;
            var ds = state.domainState;
            var d = state.decisions;
            var results;

            if (period === 1) {
                results = this._calcRound1(ds, d);
            } else if (period === 2) {
                results = this._calcRound2(ds, d);
            } else {
                results = this._calcRound3(ds, d);
            }

            ds.revenueHistory.push(ds.annualRevenue);
            ds.npsHistory.push(ds.nps);
            ds.sustainHistory.push(ds.sustainabilityIndex);
            ds.communityHistory.push(ds.communityScore);

            var revScore = Math.min(100, (ds.cumulativeRevenue / 1500) * 100);
            var npsScore = Math.min(100, ds.nps);
            var susScore = Math.min(100, ds.sustainabilityIndex);
            var comScore = Math.min(100, ds.communityScore);
            var overall = Math.round((revScore * 0.25) + (npsScore * 0.25) + (susScore * 0.25) + (comScore * 0.25));
            ds.overallScoreHistory.push(overall);

            results.overallScore = overall;
            results.nps = ds.nps;
            results.sustainability = ds.sustainabilityIndex;
            results.community = ds.communityScore;

            // FIX(v1.1.0): advance synchronously to the next round. The previous
            // setTimeout closure read state.currentPeriod AFTER the framework had
            // incremented it, so it showed round N+2's decision panel. Most damaging:
            // on the real Round 2 the learner saw Round 3's panel while validateDecisions
            // read Round 2's hidden inputs at their defaults — the learner's Round 2
            // choices were silently discarded. Guard on state identity so the deep-cloned
            // competition preview never toggles the live panels.
            if (window.mySimulation && state === window.mySimulation.state) {
                var nextPeriod = (state.currentPeriod || 1) + 1;
                if (nextPeriod <= this.ROUND_BRIEFINGS.length) {
                    this._updateBriefing({ currentPeriod: nextPeriod, domainState: ds });
                }
            }

            return results;
        }

        _calcRound1(ds, d) {
            var seg = this.SEGMENTS[d.segment] || this.SEGMENTS.couples;
            var brand = this.BRANDS[d.brand] || this.BRANDS.heritage;
            var brandFit = brand[d.segment] || 1.0;

            var digitalEff = (d.digital / 100) * 0.18;
            var otaEff = (d.ota / 100) * 0.15;
            var prEff = (d.pr / 100) * 0.20;
            var remaining = Math.max(0, 100 - d.digital - d.ota - d.pr);
            var partnerEff = (remaining * 0.6 / 100) * 0.14;
            var traditionalEff = (remaining * 0.4 / 100) * 0.08;
            var totalEff = digitalEff + otaEff + prEff + partnerEff + traditionalEff;

            var channelWeight = d.digital + d.ota + d.pr;
            var channelSynergy = 1.0;
            if (channelWeight > 0) {
                channelSynergy = ((d.digital / channelWeight) * seg.digital +
                                  (d.ota / channelWeight) * seg.ota +
                                  (d.pr / channelWeight) * seg.pr);
            }

            var competitorEffect = 0.95;
            var visitors = 1.2 * (1 + totalEff * 0.25) * brandFit * channelSynergy * seg.volumeFactor * competitorEffect;
            visitors = Math.round(visitors * 100) / 100;

            var avgSpend = seg.spend * brand.premium;
            avgSpend = Math.round(avgSpend);

            var avgStay = 3.5;
            var annualRevenue = Math.round(visitors * avgSpend * avgStay);

            var npsChange = 0;
            if (brandFit >= 1.2) npsChange = 6;
            else if (brandFit >= 1.0) npsChange = 3;
            else if (brandFit < 0.7) npsChange = -5;
            else npsChange = -2;

            ds.visitors = visitors;
            ds.avgSpend = avgSpend;
            ds.annualRevenue = annualRevenue;
            ds.cumulativeRevenue += annualRevenue;
            ds.nps = Math.max(0, Math.min(100, ds.nps + npsChange));
            ds.brandPosition = d.brand;
            ds.targetSegment = d.segment;

            var eventMsg = window.mySimulation.t('event1_text');
            if (d.segment === 'adventure' || d.brand === 'adventure_brand') {
                ds.visitors = Math.round((ds.visitors + 0.04) * 100) / 100;
                eventMsg += '<br>' + window.mySimulation.t('event1_bonus');
            }
            ds.eventLog = eventMsg;

            ds.sustainabilityIndex = Math.min(100, ds.sustainabilityIndex + 2);
            ds.communityScore = Math.min(100, ds.communityScore + (brandFit >= 1.0 ? 3 : -3));
            ds.budget = 15;

            return {
                period: 1,
                visitors: ds.visitors,
                avgSpend: avgSpend,
                annualRevenue: annualRevenue,
                nps: ds.nps,
                sustainability: ds.sustainabilityIndex,
                community: ds.communityScore
            };
        }

        _calcRound2(ds, d) {
            var culturalLift = (d.cultural / 100) * 0.15;
            var gastroLift = (d.gastro / 100) * 0.12;
            var beachRepeat = (d.beach / 100) * 0.08;
            var spendLift = culturalLift + gastroLift;

            ds.avgSpend = Math.round(ds.avgSpend * (1 + spendLift));

            var comm = d.commercialization;
            ds.commercialization = comm;
            var volumeBoost = (comm - 5) / 50;
            ds.visitors = Math.round((ds.visitors * (1 + volumeBoost + beachRepeat)) * 100) / 100;
            ds.visitors = Math.max(0.5, ds.visitors);

            var avgStay = 3.5;
            ds.annualRevenue = Math.round(ds.visitors * ds.avgSpend * avgStay);
            ds.cumulativeRevenue += ds.annualRevenue;

            var npsChange = 0;
            if (comm >= 8) npsChange -= (comm - 7) * 4;
            else if (comm <= 3) npsChange += (4 - comm) * 3;
            if (d.cultural >= 30) npsChange += 5;
            if (d.gastro >= 15) npsChange += 3;
            ds.nps = Math.max(0, Math.min(100, ds.nps + npsChange));

            var communityChange = 0;
            if (comm >= 8) communityChange -= (comm - 7) * 6;
            else if (comm <= 3) communityChange += (4 - comm) * 5;
            if (d.cultural >= 30) communityChange += 5;
            ds.communityScore = Math.max(0, Math.min(100, ds.communityScore + communityChange));

            var sustainChange = 0;
            if (comm <= 4) sustainChange += 8;
            else if (comm >= 8) sustainChange -= 5;
            if (d.cultural >= 20) sustainChange += 4;
            ds.sustainabilityIndex = Math.max(0, Math.min(100, ds.sustainabilityIndex + sustainChange));

            var eventMsg = window.mySimulation.t('event2_text');
            if (d.gastro >= 15) {
                ds.annualRevenue = Math.round(ds.annualRevenue * 1.08);
                ds.cumulativeRevenue += Math.round(ds.annualRevenue * 0.08);
                eventMsg += '<br>' + window.mySimulation.t('event2_bonus');
            }
            ds.eventLog = eventMsg;
            ds.budget = 15;

            return {
                period: 2,
                visitors: ds.visitors,
                avgSpend: ds.avgSpend,
                annualRevenue: ds.annualRevenue,
                nps: ds.nps,
                sustainability: ds.sustainabilityIndex,
                community: ds.communityScore
            };
        }

        _calcRound3(ds, d) {
            var dailyDemand = Math.round((ds.visitors * 1000000) / 365);
            var cap = d.visitorCap;
            var capEnforced = false;

            if (cap < dailyDemand) {
                ds.visitors = Math.round((cap * 365 / 1000000) * 100) / 100;
                capEnforced = true;
            }

            var npsChange = 0;
            if (capEnforced) {
                npsChange += 8;
            } else if (dailyDemand > 5500) {
                var excess = dailyDemand - 5500;
                npsChange -= Math.floor(excess / 500) * 2;
            }

            var communityShareEffect = 0;
            if (d.communityShare >= 10) communityShareEffect = 20;
            else if (d.communityShare >= 5) communityShareEffect = 10;
            else communityShareEffect = -12;
            ds.communityScore = Math.max(0, Math.min(100, ds.communityScore + communityShareEffect));

            var sustainDelta = 0;
            if (d.certInvest >= 15) sustainDelta = 25;
            else if (d.certInvest >= 10) sustainDelta = 18;
            else if (d.certInvest >= 5) sustainDelta = 10;
            else sustainDelta = -3;

            if (capEnforced) sustainDelta += 10;
            var capCompliance = (cap <= 5500) ? 1.0 : Math.max(0, 1.0 - (cap - 5500) / 5000);
            sustainDelta += Math.round(capCompliance * 8);
            ds.sustainabilityIndex = Math.max(0, Math.min(100, ds.sustainabilityIndex + sustainDelta));

            if (d.expansion >= 5) {
                npsChange += 4;
                ds.communityScore = Math.min(100, ds.communityScore + 5);
            }

            ds.nps = Math.max(0, Math.min(100, ds.nps + npsChange));

            var demandBonus = 1.0;
            if (d.certInvest >= 10 && d.communityShare >= 8) {
                demandBonus += 0.08;
            }
            if (d.communityShare >= 10) {
                demandBonus += 0.03;
            }
            ds.visitors = Math.round(ds.visitors * demandBonus * 100) / 100;

            var avgStay = 3.5;
            ds.annualRevenue = Math.round(ds.visitors * ds.avgSpend * avgStay);

            var hurricaneDamage = 0;
            if (d.certInvest >= 10) {
                hurricaneDamage = 0.03;
            } else {
                hurricaneDamage = 0.08;
            }
            ds.annualRevenue = Math.round(ds.annualRevenue * (1 - hurricaneDamage));
            ds.cumulativeRevenue += ds.annualRevenue;

            var shareAmount = Math.round(ds.annualRevenue * (d.communityShare / 100));

            var eventMsg = window.mySimulation.t('event3_text');
            if (d.certInvest >= 10) {
                eventMsg += '<br>' + window.mySimulation.t('event3_bonus');
            }
            ds.eventLog = eventMsg;
            ds.budget = 15;

            return {
                period: 3,
                visitors: ds.visitors,
                avgSpend: ds.avgSpend,
                annualRevenue: ds.annualRevenue,
                nps: ds.nps,
                sustainability: ds.sustainabilityIndex,
                community: ds.communityScore,
                communityShareAmount: shareAmount
            };
        }

